// Some portions generated by Claude
import type { GraphNode } from "./graph-types.ts";

export type FindMatch = {
  node: GraphNode;
  /** Where the term was found: in the label, or only in the IRI. */
  in: "label" | "iri";
};

/** How well a label matches; lower is better, null when it does not contain the term. */
function labelRank(label: string, term: string) {
  if (label === term) return 0;
  if (label.startsWith(term)) return 1;
  if (label.split(/[\s\-_/.,:;()]+/).some((word) => word.startsWith(term))) return 2;
  return label.includes(term) ? 3 : null;
}

/**
 * The loaded nodes whose label or IRI contains the term, best first: an exact label, a label that starts with it, a
 * word that starts with it, a label that contains it, then an IRI that contains it; shorter labels first within each.
 */
export function findNodes(nodes: readonly GraphNode[], term: string, limit = 8): FindMatch[] {
  const needle = term.trim().toLocaleLowerCase();
  if (!needle) return [];
  const ranked: Array<{ match: FindMatch; rank: number }> = [];
  for (const node of nodes) {
    const rank = labelRank(node.label.toLocaleLowerCase(), needle);
    if (rank !== null) ranked.push({ match: { node, in: "label" }, rank });
    else if (node.kind !== "literal" && node.id.toLocaleLowerCase().includes(needle))
      ranked.push({ match: { node, in: "iri" }, rank: 4 });
  }
  return ranked
    .sort(
      (left, right) =>
        left.rank - right.rank ||
        left.match.node.label.length - right.match.node.label.length ||
        left.match.node.label.localeCompare(right.match.node.label),
    )
    .slice(0, limit)
    .map(({ match }) => match);
}
